import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.ieP-ZwyM.js";const k=JSON.parse('{"title":"Rotating APP_KEY","description":"","frontmatter":{},"headers":[],"relativePath":"operations/app-key.md","filePath":"operations/app-key.md","lastUpdated":1793170150000}'),n={name:"operations/app-key.md"};function i(d,e,r,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="rotating-app_key" tabindex="-1">Rotating APP_KEY <a class="header-anchor" href="#rotating-app_key" aria-label="Permalink to &quot;Rotating APP_KEY&quot;">​</a></h1><p><code>APP_KEY</code> keys:</p><ul><li>session ids, JWT signatures and refresh tokens;</li><li>the links of password resets and invitations;</li><li>the secrets of the settings and the <a href="./../digging-deeper/encryption.html">encrypted columns</a>.</li></ul><p>Rotate it when it may have leaked. This page is the procedure: a restart of every process, a re-encryption run, a verification run, and a second restart.</p><h2 id="what-a-new-key-does" tabindex="-1">What a new key does <a class="header-anchor" href="#what-a-new-key-does" aria-label="Permalink to &quot;What a new key does&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>After rotation</th></tr></thead><tbody><tr><td>Admin sessions</td><td>ended (everyone signs in again)</td></tr><tr><td>JWT access and refresh tokens</td><td>ended</td></tr><tr><td>Reset and invitation links</td><td>dead (ask for new ones; send invitations again)</td></tr><tr><td>Secret settings, encrypted columns</td><td>still readable while the old key is in <code>APP_PREVIOUS_KEYS</code>; <code>key:reencrypt</code> moves them to the new key</td></tr><tr><td>Personal API tokens (<code>rcms_…</code>)</td><td><strong>kept</strong> (not keyed by <code>APP_KEY</code>): revoke them if they may have leaked too</td></tr></tbody></table><p>The old key in <code>APP_PREVIOUS_KEYS</code> only opens encrypted values. It never brings back a session, a token or a link.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><p>Generate the new key:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key:generate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --show</span></span></code></pre></div><p><code>--show</code> prints it. Without it, the command writes <code>APP_KEY</code> to <code>.env</code>, and refuses to replace an existing one unless you add <code>--force</code>.</p></li><li><p>In the environment of <strong>every</strong> web and worker process, <strong>and of the shell, job or container where you run the <code>rustcms</code> commands below</strong> (each command reads its own configuration):</p><ul><li><code>APP_KEY</code> = the new key;</li><li><code>APP_PREVIOUS_KEYS</code> = the old key, plus any older keys still listed there (comma-separated).</li></ul><p>A command run with the old environment checks the old key: its results prove nothing about the new one.</p></li><li><p>Stop <strong>every</strong> process, then start them all. A rolling restart does not work: a process still on the old key cannot read what the new ones seal.</p></li><li><p>Run <code>rustcms key:reencrypt</code>. It re-seals every registered encrypted column and every settings secret with the new key, and prints one line per column:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>integrations.api_token: 0 current, 12 moved, 0 changed meanwhile, 0 unreadable</span></span>
<span class="line"><span>settings: 3 current, 1 moved, 0 changed meanwhile, 0 unreadable</span></span></code></pre></div><p>It fails (non-zero exit) only when a row changed meanwhile or a value is unreadable; rows it moved count as done. Running it again is safe.</p><ul><li><strong>Changed meanwhile:</strong> someone wrote the row during the run. Run the command again.</li><li><strong>Unreadable:</strong> listed by table, column and key (or settings group). No key of this command&#39;s keyring opens them. First check that the command runs with the new <code>APP_KEY</code> and every previous key you still have, and that a column registered with <code>Binding::Row</code> is really sealed with <code>.row(id)</code> (and the reverse). A value also reads as unreadable when it is damaged. Set a secret again only once you know no key you hold opens it.</li><li><code>--list</code> shows the columns and settings it covers; <code>--batch &lt;n&gt;</code> (1 to 10000, default 500) sets how many rows it reads at a time.</li></ul></li><li><p>Check, in the same environment (new <code>APP_KEY</code>): <code>rustcms key:reencrypt --dry-run</code> must succeed. A dry run fails while any value is still to move, so success means everything is under the new key.</p></li><li><p>Remove <code>APP_PREVIOUS_KEYS</code> everywhere and restart every process. Keep the old key with the backups that still need it (<a href="#backups">below</a>).</p></li><li><p>Revoke API tokens if needed:</p><ul><li><p>each user&#39;s <em>Sign out other sessions</em> (Account page) ends their other sessions and revokes their tokens;</p></li><li><p>or set <code>revoked_at</code> on the rows of <code>personal_access_tokens</code>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> personal_access_tokens </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> revoked_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CURRENT_TIMESTAMP </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> revoked_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></li></ul></li></ol><h2 id="setting-the-keys" tabindex="-1">Setting the keys <a class="header-anchor" href="#setting-the-keys" aria-label="Permalink to &quot;Setting the keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Config key</th><th>Form</th></tr></thead><tbody><tr><td><code>APP_KEY</code></td><td><code>app.key</code></td><td>the key <code>key:generate</code> prints</td></tr><tr><td><code>APP_PREVIOUS_KEYS</code></td><td><code>app.previous_keys</code></td><td>comma-separated keys, or a TOML list in <code>config/app.toml</code></td></tr></tbody></table><p>Both also accept a <code>_FILE</code> variant (<code>APP_KEY_FILE</code>, <code>APP_PREVIOUS_KEYS_FILE</code>) that reads the value from a file, for Docker and Kubernetes secrets (<a href="./../getting-started/configuration.html">Configuration</a>).</p><p>Boot fails when <code>APP_PREVIOUS_KEYS</code> lists a key twice or lists the current <code>APP_KEY</code>. Errors never quote a key.</p><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h2><p>Old backups hold values sealed with the old key, and a backup taken during an unfinished rotation can hold values under several keys. They open again only with those keys, as <code>APP_KEY</code> or in <code>APP_PREVIOUS_KEYS</code>. Keep every key a backup needs with it, or destroy both (<a href="./backup-restore.html">Backup and restore</a>).</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../digging-deeper/encryption.html">Encrypted columns</a></li><li><a href="./../security/revocation.html">Revocation</a></li><li><a href="./../security/production.html">Production checklist</a></li></ul>`,17)])])}const u=t(n,[["render",i]]);export{k as __pageData,u as default};
